head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > getUncheckedXML]<br/>특정 Body Column 이 체크 해제 상태인 Row 의 데이터를 XML 객체로 반환합니다. inputType 이 'checkbox','radio','custom' 인 경우에만 동작합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터로 체크 상태를 조회할 Body Column 의 인덱스를 설정해야 합니다.",
        "특정 Body Column 이 체크 해제 상태인 Row 의 데이터를 XML 객체로 반환해야 합니다.",
        "inputType 이 'checkbox','radio','custom' 인 경우에만 동작해야 합니다.",
        "Body Column 의 inputType 이 'checkbox','radio','custom' 이 아니면 빈 XML 객체를 반환해야 합니다.",
        "DataList 의 baseNode 속성값이 Root 노드의 태그명으로 적용되고, 반복되는 데이터 노드의 태그엔 repeatNode 속성값이 적용되어야 합니다.",
        "데이터 태그는 'status' 속성으로 Row 의 상태코드값, 'statusValue' 속성으로 Row 의 상태값, 'index' 속성으로 Row 의 인덱스값이 설정되어야 합니다.",
        "데이터 태그의 하위 태그로 DataList 의 Column ID 와 Column 값이 반복되어야 합니다.",
        "inputType='custom' 이면 실제 Body Cell 의 inputType 이 'checkbox','radio' 인 Cell 만 처리해야 합니다.",
        "disabled/readOnly 상태인 Body Cell 의 Row 데이터도 결과에 포함되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 inputType 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    // DataList baseNode="list" repeatNode="map" → 반환 XML Root list 태그, 데이터 노드 map 태그
    $c.gcm.createLabel('label="0:chk(checkbox) / 1:name(text) / 2:birth(text) / 3:rdo(radio) / 4:cst(custom, Row1·3=text·radio미체크)  ·  DataList baseNode=list·repeatNode=map(→ XML root=list 태그, 데이터노드=map 태그), 미체크 변경행 statusValue=U"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - baseNode="list" repeatNode="map" : getUncheckedXML 반환 XML 의 Root/데이터 노드 태그명 결정
    // - chk    : checkbox(binary) 원본값 1/0  → 조회 대상 Column(인덱스 0)
    // - name   : text
    // - birth  : text
    // - rdo    : radio(binary)
    // - cst    : custom 컬럼 원본값 (checkbox/radio 셀은 trueValue 값, text 셀은 표시 문자열)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="birth" name="birth" dataType="text"></w2:column>';
    strDlt += '<w2:column id="rdo" name="rdo" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cst" name="cst" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // chk : Row0/Row2/Row4 = 체크(trueValue "1"), Row1/Row3 = 미체크(falseValue "0")
    //       → getUncheckedXML(chk) 는 미체크 행 Row1/Row3 만 반환
    // rdo : radio 단일선택 → Row1(KIM)만 "1"(체크) → getUncheckedXML(rdo) 는 Row1 제외 나머지 반환
    // cst : Row0=checkbox(1=체크), Row1=text, Row2=checkbox(1=체크), Row3=radio(0=미체크), Row4=checkbox(1=체크)
    //       → custom 미체크 반환은 radio 미체크 Row3 (checkbox 는 모두 체크, text 셀은 제외)
    let jsonData = [
        { "chk": "1", "name": "HONG", "birth": "19850315", "rdo": "0", "cst": "1"    },
        { "chk": "0", "name": "KIM",  "birth": "19900720", "rdo": "1", "cst": "text" },
        { "chk": "1", "name": "LEE",  "birth": "19880103", "rdo": "0", "cst": "1"    },
        { "chk": "0", "name": "PARK", "birth": "19920512", "rdo": "0", "cst": "0"    },
        { "chk": "1", "name": "CHOI", "birth": "19870928", "rdo": "0", "cst": "1"    }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    // setCellInputTypeCustom=true → custom 컬럼에 setCellInputType 으로 행별 inputType 부여 가능
    let properties = {
        dataList: "data:dlt_bind",
        setCellInputTypeCustom: "true",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 5컬럼)
    // 마지막 cst 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:720px;height:260px;">';
    strTarget += '<w2:caption style="" id="caption1" value="getUncheckedXML 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol1" value="chk(checkbox)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="이름"></w2:column>';
    strTarget += '<w2:column width="140" style="" inputType="text" id="hcol3" value="생년월일"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol4" value="rdo(radio)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol5" value="cst(custom)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : chk (checkbox, valueType=binary) - trueValue="1" falseValue="0"  → 조회 대상 Column
    strTarget += '<w2:column width="120" style="" inputType="checkbox" valueType="binary" id="chk" dataList="chk" trueValue="1" falseValue="0"></w2:column>';
    // index 1 : name (text)
    strTarget += '<w2:column width="120" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 2 : birth (text)
    strTarget += '<w2:column width="140" style="" inputType="text" id="birth" dataList="birth"></w2:column>';
    // index 3 : rdo (radio, valueType=binary) - 단일 선택 (Row1 만 체크). getUncheckedXML 동작 inputType 중 radio 검증
    strTarget += '<w2:column width="120" style="" inputType="radio" valueType="binary" id="rdo" dataList="rdo" trueValue="1" falseValue="0"></w2:column>';
    // index 4 : cst (custom) - 행별 inputType 혼합 (setCellInputType 으로 지정), width="*"
    strTarget += '<w2:column width="*" style="" inputType="custom" id="cst" dataList="cst" trueValue="1" falseValue="0"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // cst(custom) 컬럼 행별 inputType 부여 (@spec1)
    //  Row0 = checkbox(1=체크), Row1 = text(체크 대상 아님), Row2 = checkbox(1=체크), Row3 = radio(0=미체크), Row4 = checkbox(1=체크)
    //  → getUncheckedXML(cst) 는 실제 checkbox/radio 셀 중 미체크인 radio Row3 만 반환 (@spec1)
    target1.setCellInputType(0, "cst", { inputType: "checkbox" });
    target1.setCellInputType(1, "cst", { inputType: "text" });
    target1.setCellInputType(2, "cst", { inputType: "checkbox" });
    target1.setCellInputType(3, "cst", { inputType: "radio" });
    target1.setCellInputType(4, "cst", { inputType: "checkbox" });

    // statusValue 검증용 : 미체크 Row1(KIM) 의 birth 셀 값을 바인딩 DataList 로 변경 → 해당 Row 상태 'U'(Updated)
    //  미변경 미체크행(Row3)은 'R'(Read) 로 데이터 태그의 statusValue 속성이 다르게 나타남
    dlt_bind.setCellData(1, "birth", "20000101");

    // 미체크 Row 중 일부를 disabled/readOnly 처리 → @spec2 (상태 무관 결과 포함) 검증
    //  Row1(chk 미체크) = setRowReadOnly, Row3(chk 미체크) = setRowDisabled
    target1.setRowReadOnly(1, true);
    target1.setRowDisabled(3, true);
}



// getUncheckedXML 확인 : par_columnInfo(컬럼 인덱스) 로 호출 → 체크 해제 상태인 Row 의 데이터를 XML 객체로 반환
//  - chk(인덱스0)  : Row0/Row2/Row4 체크 → 미체크 Row1/Row3 마다 Root list 하위 map(status statusValue id) + Column ID 하위태그 반환
//  - name(인덱스1) : text 컬럼 → 빈 XML 객체 (@description / @return)
//  - rdo(인덱스3)  : radio 단일선택 → Row1 만 체크 → Row1 제외 나머지 반환 (checkbox/radio/custom 동작 검증)
//  - cst(인덱스4)  : custom → 실제 radio/checkbox 셀 중 미체크인 radio Row3 만 처리, text 셀(Row1)/checkbox 체크(Row0,2,4) 제외 (@spec1)
scwin.btn_getUncheckedXML_onclick = function () {
    // columnInfo 는 컬럼 인덱스(Number) 로 전달
    let colIndex = Number(par_columnInfo.getValue());
    let rtnXML = target1.getUncheckedXML(colIndex);

    // 반환은 XML 객체(Document) → WebSquare.xml.serialize 로 문자열 직렬화하여 구조 확인
    //  Root list 태그 / 데이터노드 map(status statusValue id) / 하위 chk·name·birth·rdo·cst 태그가 보이도록 출력
    let xmlStr = WebSquare.xml.serialize(rtnXML);
    let out = "getUncheckedXML(" + colIndex + ") 반환 XML 직렬화";
    out += "\n" + xmlStr;
    wf_body_bottom.getObj("scwin").setReturnValue(out);
}
